<?php
require_once 'includes.php';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=post('action');if($a==='save'){$id=(int)post('id','0');$d=[post('hostel_name'),post('location'),post('gender_type')];if(!$d[0]||!$d[1])throw new Exception('Hostel name and location are required.');if($id){$d[]=$id;$q=$pdo->prepare("UPDATE hostels SET hostel_name=?,location=?,gender_type=? WHERE hostel_id=?");$q->execute($d);flash('Hostel updated.');}else{$q=$pdo->prepare("INSERT INTO hostels(hostel_name,location,gender_type) VALUES(?,?,?)");$q->execute($d);flash('Hostel added.');}}elseif($a==='delete'){$q=$pdo->prepare("DELETE FROM hostels WHERE hostel_id=?");$q->execute([(int)post('id')]);flash('Hostel deleted.');}}catch(Throwable $e){flash($e->getMessage(),'error');}redirect('hostels.php');}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM hostels WHERE hostel_id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$rows=$pdo->query("SELECT h.*,COUNT(r.room_id) room_count FROM hostels h LEFT JOIN rooms r ON r.hostel_id=h.hostel_id GROUP BY h.hostel_id ORDER BY h.hostel_id DESC")->fetchAll();
page_header('Hostel directory','hostels.php');?>
<div class="toolbar"><span class="muted">Manage hostel locations and accommodation categories.</span><a class="btn" href="#hostel-form">＋ Add hostel</a></div>
<section class="form-card" id="hostel-form"><h3><?=$edit?'Edit hostel':'Add a hostel'?></h3><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['hostel_id']??'0')?>"><div class="form-grid">
<div class="field"><label>Hostel name *</label><input name="hostel_name" required value="<?=e($edit['hostel_name']??'')?>"></div><div class="field"><label>Location *</label><input name="location" required value="<?=e($edit['location']??'')?>"></div>
<div class="field"><label>Category</label><select name="gender_type"><?php foreach(['Female','Male','Any'] as $g):?><option <?=$g===($edit['gender_type']??'Female')?'selected':''?>><?=$g?></option><?php endforeach;?></select></div></div><div class="form-actions"><button class="btn">Save hostel</button><?php if($edit):?><a class="btn secondary" href="hostels.php">Cancel</a><?php endif;?></div></form></section>
<h3 class="section-title">Hostel records · <?=count($rows)?></h3><div class="table-wrap"><table><thead><tr><th>ID</th><th>Hostel</th><th>Location</th><th>Category</th><th>Rooms</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['hostel_id']?></td><td><?=e($r['hostel_name'])?></td><td><?=e($r['location'])?></td><td><?=e($r['gender_type'])?></td><td><?=$r['room_count']?></td><td><div class="actions"><a class="btn small secondary" href="?edit=<?=$r['hostel_id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete hostel?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['hostel_id']?>"><button class="btn small danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div>
<?php page_footer();?>
